import React, { useState, useEffect } from 'react';
import './../styles/Grid.css';

const Grid = ({ onGridItemClick }) => {
    const [gridData, setGridData] = useState([]);

    useEffect(() => {
        fetch('/gridData.json')
            .then((response) => response.json())
            .then((data) => {
                console.log('Fetched JSON data:', data);
                setGridData(data);
            })
            .catch((error) => console.error('Error fetching grid data:', error));
    }, []);

    const filteredItems = gridData.filter(item => !item.empty);

    return (
        <div className="image-grid">
            {filteredItems.map((item, index) => (
                <div
                    className="grid-item"
                    key={index} // Use index as key since you don't have a unique id
                    onClick={() => onGridItemClick(item.text, item.carousel ? item.images : [item.image], item.carousel)}
                >
                    {item.carousel ? (
                        item.images && item.images.length > 0 && (
                            <img src={item.images[0]} alt={item.text} />
                        )
                    ) : (
                        item.image && (
                            <img src={item.image} alt={item.text} />
                        )
                    )}
                </div>
            ))}
        </div>
    );
};

export default Grid;
